import { Avatar, Card, CardActions, CardContent, CardHeader, CardMedia, Chip, Collapse, Grid, IconButton, Typography } from '@mui/material'
import React from 'react'
import LaunchIcon from '@mui/icons-material/Launch';
import { Swiper, SwiperSlide } from 'swiper/react';
import { makeStyles } from "@mui/styles";
import 'swiper/css'
import { Navigation, Pagination, Scrollbar, A11y } from 'swiper/modules';

const useStyles = makeStyles((theme) => ({
  card: {
    backgroundColor: theme.palette.secondary.primary,
    color: theme.palette.primary,
    marginBottom:"10%",
  },
  cardHeader: {
    backgroundColor: theme.palette.primary.main,
    color: theme.palette.secondary.main,

  },
  cardContent: {
    backgroundColor: theme.palette.primary.main,
    color: theme.palette.secondary.main,
  },
  cardActions: {
    backgroundColor: theme.palette.primary.main,
    color: theme.palette.secondary.main,
  },
}));

function ProjectCard({project}) {
  const [expanded, setExpanded] = React.useState(false);

  const handleExpandClick = () => {
    setExpanded(!expanded);
  };
  const classes = useStyles();
  
  return (
    
    <Card className={classes.card} >
      
      <Swiper
        modules={[Navigation, Pagination, Scrollbar, A11y]}
        spaceBetween={50}
        slidesPerView={1}
        navigation={{ prevEl: '.swiper-button-prev', nextEl: '.swiper-button-next' }} // Add this line
        onSlideChange={() => console.log('slide change')}
        onSwiper={(swiper) => console.log(swiper)}
>
      <SwiperSlide>
        <img src={project.images[0]}  alt=''/>
      </SwiperSlide>
      <SwiperSlide>
        <img src={project.images[0]}  alt=''/>
      </SwiperSlide>
  
    </Swiper>
      <CardContent className={classes.cardContent}>
        <Typography variant="h5" color="text.secondary">
          {project.title}
        </Typography>
        <Typography variant="body2" color="text.secondary">
          {project.desc}
        </Typography>
        <div>
          <br />
            {
              project.tags.map((tag, index)=>{
                return(
                  <Chip key={index} sx={{marginRight:"3px"}} label={tag} size="small" />
                )
              })
            }
        </div>
      </CardContent>
      <CardActions
        className={classes.cardActions} disableSpacing>
        <IconButton onClick={()=>handleExpandClick(project.link)} flo aria-label="add to favorites">
          <LaunchIcon />
        </IconButton>
      </CardActions>
    </Card>
  )
}

export default ProjectCard